    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode n = root;
        while (true) {
            while (n != null) { st.push(n); n = n.left; }
            n = st.pop();
            if (--k == 0) return n.val;
            n = n.right;
        }
    }
}

