		next := []*TreeNode{}
		for _, n := range q {
			if n.Left == nil && n.Right == nil {
				return depth
			}
			if n.Left != nil {
				next = append(next, n.Left)
			}
			if n.Right != nil {
				next = append(next, n.Right)
			}
		}
		q, depth = next, depth+1
	}
}

