func longestZigZag(root *TreeNode) int {
	best := 0
	var dfs func(*TreeNode) (int, int) // zigzag length (in edges) starting with a left / right step
	dfs = func(node *TreeNode) (int, int) {
		if node == nil {
			return -1, -1
		}
		_, lr := dfs(node.Left)
		rl, _ := dfs(node.Right)
		left, right := lr+1, rl+1
		best = max(best, left, right)
		return left, right
	}
	dfs(root)
	return best
}

